mapper.select:
select * from ai_text_to_sql_run


        and (
            original_question like concat('%', #{keyword}, '%')
            or error_message like concat('%', #{keyword}, '%')
        )


        and conversation_id = #{conversationId}


        and source_type = #{sourceType}


        and status = #{status}


        and feedback_result is null


        and feedback_result = #{feedbackResult}


order by created_at desc, id desc
